import React, { useEffect, useMemo, useState } from "react";

const TAU = Math.PI * 2;

function polar(cx, cy, rx, ry, angle) {
  return {
    x: cx + rx * Math.cos(angle),
    y: cy + ry * Math.sin(angle),
  };
}

function areaPath(cx, cy, rx, ry, a1, a2) {
  const p1 = polar(cx, cy, rx, ry, a1);
  const p2 = polar(cx, cy, rx, ry, a2);
  const largeArc = Math.abs(a2 - a1) > Math.PI ? 1 : 0;
  return [
    `M ${cx} ${cy}`,
    `L ${p1.x} ${p1.y}`,
    `A ${rx} ${ry} 0 ${largeArc} 1 ${p2.x} ${p2.y}`,
    "Z",
  ].join(" ");
}

export default function KeplersLawsVisualizer() {
  const [law, setLaw] = useState(2);
  const [running, setRunning] = useState(true);
  const [time, setTime] = useState(0);

  useEffect(() => {
    if (!running) return;
    let frame;
    let previous = performance.now();

    const animate = (now) => {
      const dt = Math.min((now - previous) / 1000, 0.05);
      previous = now;
      setTime((t) => t + dt * 0.55);
      frame = requestAnimationFrame(animate);
    };

    frame = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(frame);
  }, [running]);

  const cx = 310;
  const cy = 190;
  const rx = 205;
  const ry = 125;

  // Elliptical orbit. The Sun is at the left focus.
  const focus = Math.sqrt(rx * rx - ry * ry);
  const sunX = cx - focus;
  const sunY = cy;

  const angle = time % TAU;

  // Variable angular speed: faster near the Sun, slower far away.
  // This is used only to visualize the qualitative consequence of Kepler's 2nd law.
  const point = polar(cx, cy, rx, ry, angle);
  const distanceFromSun = Math.hypot(point.x - sunX, point.y - sunY);
  const speedFactor = Math.min(2.3, Math.max(0.65, 330 / distanceFromSun));

  const sweep = 0.18 * speedFactor;
  const previousAngle = angle - sweep;

  const pPrevious = polar(cx, cy, rx, ry, previousAngle);

  const area1 = areaPath(cx, cy, rx, ry, previousAngle, angle);
  const area2 = areaPath(
    cx,
    cy,
    rx,
    ry,
    angle + Math.PI,
    previousAngle + Math.PI
  );

  const lawText = {
    1: {
      title: "Kepler's First Law — Law of Orbits",
      text: "Every planet moves in an elliptical orbit with the Sun at one focus.",
    },
    2: {
      title: "Kepler's Second Law — Law of Areas",
      text: "The line joining the planet and the Sun sweeps out equal areas in equal intervals of time.",
    },
    3: {
      title: "Kepler's Third Law — Law of Periods",
      text: "The square of the orbital period is proportional to the cube of the semi-major axis: T² ∝ a³.",
    },
  };

  const current = lawText[law];

  return (
    <div
      style={{
        width: "100%",
        background: "#fff",
        border: "1px solid #e5e7eb",
        borderRadius: 18,
        padding: 22,
        boxSizing: "border-box",
      }}
    >
      <div style={{ marginBottom: 18 }}>
        <h2
          style={{
            margin: 0,
            color: "#071A3D",
            fontSize: 22,
            fontWeight: 800,
          }}
        >
          Kepler's Laws — Interactive Visualization
        </h2>

        <p
          style={{
            margin: "8px 0 0",
            color: "#526B8D",
            lineHeight: 1.6,
          }}
        >
          {current.text}
        </p>
      </div>

      <div
        style={{
          display: "flex",
          gap: 8,
          flexWrap: "wrap",
          marginBottom: 18,
        }}
      >
        {[1, 2, 3].map((n) => (
          <button
            key={n}
            type="button"
            onClick={() => setLaw(n)}
            style={{
              border: law === n ? "2px solid #2563EB" : "1px solid #dbe3ef",
              background: law === n ? "#EFF6FF" : "#fff",
              color: law === n ? "#2563EB" : "#526B8D",
              borderRadius: 10,
              padding: "9px 14px",
              fontWeight: 800,
              cursor: "pointer",
            }}
          >
            {n === 1 ? "1st Law" : n === 2 ? "2nd Law" : "3rd Law"}
          </button>
        ))}

        <button
          type="button"
          onClick={() => setRunning((v) => !v)}
          style={{
            marginLeft: "auto",
            border: "1px solid #F5A000",
            background: "#FFF9EE",
            color: "#B45309",
            borderRadius: 10,
            padding: "9px 14px",
            fontWeight: 800,
            cursor: "pointer",
          }}
        >
          {running ? "Pause" : "Play"}
        </button>
      </div>

      <div
        style={{
          overflowX: "auto",
          background: "#F8FAFC",
          borderRadius: 14,
          border: "1px solid #E7ECF3",
        }}
      >
        <svg
          viewBox="0 0 620 380"
          width="100%"
          style={{
            minWidth: 560,
            display: "block",
          }}
        >
          <defs>
            <filter id="planetShadow">
              <feDropShadow dx="0" dy="2" stdDeviation="2" floodOpacity="0.2" />
            </filter>
          </defs>

          {/* Orbit */}
          <ellipse
            cx={cx}
            cy={cy}
            rx={rx}
            ry={ry}
            fill="none"
            stroke="#94a3b8"
            strokeWidth="2"
            strokeDasharray="7 6"
          />

          {/* Semi-major axis */}
          <line
            x1={cx - rx}
            y1={cy}
            x2={cx + rx}
            y2={cy}
            stroke="#cbd5e1"
            strokeWidth="1"
          />

          {/* Sun */}
          <circle
            cx={sunX}
            cy={sunY}
            r="19"
            fill="#F5A000"
            filter="url(#planetShadow)"
          />
          <text
            x={sunX}
            y={sunY + 39}
            textAnchor="middle"
            fontSize="13"
            fontWeight="800"
            fill="#B45309"
          >
            Sun
          </text>

          {law === 2 && (
            <>
              {/* Equal-area demonstration */}
              <path
                d={area1}
                fill="#2563EB"
                fillOpacity="0.20"
                stroke="#2563EB"
                strokeWidth="2"
              />
              <path
                d={area2}
                fill="#16A34A"
                fillOpacity="0.20"
                stroke="#16A34A"
                strokeWidth="2"
              />

              <line
                x1={sunX}
                y1={sunY}
                x2={point.x}
                y2={point.y}
                stroke="#2563EB"
                strokeWidth="2"
              />

              <line
                x1={sunX}
                y1={sunY}
                x2={pPrevious.x}
                y2={pPrevious.y}
                stroke="#2563EB"
                strokeWidth="2"
              />

              <line
                x1={sunX}
                y1={sunY}
                x2={polar(cx, cy, rx, ry, angle + Math.PI).x}
                y2={polar(cx, cy, rx, ry, angle + Math.PI).y}
                stroke="#16A34A"
                strokeWidth="2"
              />

              <text
                x="95"
                y="55"
                fontSize="13"
                fontWeight="800"
                fill="#2563EB"
              >
                Swept area A₁
              </text>

              <text
                x="410"
                y="55"
                fontSize="13"
                fontWeight="800"
                fill="#15803D"
              >
                Equal swept area A₂
              </text>
            </>
          )}

          {/* Planet */}
          <circle
            cx={point.x}
            cy={point.y}
            r="9"
            fill="#2563EB"
            filter="url(#planetShadow)"
          />

          <text
            x={point.x + 14}
            y={point.y - 12}
            fontSize="13"
            fontWeight="800"
            fill="#071A3D"
          >
            Planet
          </text>
        </svg>
      </div>

      {law === 2 && (
        <div
          style={{
            marginTop: 16,
            padding: 16,
            background: "#EFF6FF",
            borderLeft: "4px solid #2563EB",
            borderRadius: "0 10px 10px 0",
          }}
        >
          <div
            style={{
              fontWeight: 800,
              color: "#071A3D",
              marginBottom: 6,
            }}
          >
            Why the two areas are equal
          </div>

          <div
            style={{
              color: "#526B8D",
              lineHeight: 1.7,
              fontSize: 14,
            }}
          >
            The gravitational force is a central force, so torque about the
            Sun is zero. Therefore angular momentum remains constant.
            Consequently, the areal velocity remains constant:
          </div>

          <div
            className="math-block"
            style={{
              marginTop: 10,
              fontWeight: 800,
              fontSize: 17,
            }}
          >
            ΔA / Δt = L / 2m = constant
          </div>

          <div
            style={{
              marginTop: 10,
              color: "#526B8D",
              fontSize: 13,
              lineHeight: 1.6,
            }}
          >
            The planet therefore moves faster near perihelion and slower near
            aphelion while sweeping equal areas in equal time intervals.
          </div>
        </div>
      )}

      {law === 1 && (
        <div
          style={{
            marginTop: 16,
            padding: 16,
            background: "#F8FAFC",
            borderRadius: 10,
            color: "#526B8D",
            lineHeight: 1.7,
          }}
        >
          The orbit is shown as an ellipse and the Sun is placed at one focus,
          not at the geometric centre.
        </div>
      )}

      {law === 3 && (
        <div
          style={{
            marginTop: 16,
            padding: 16,
            background: "#FFF9EE",
            borderLeft: "4px solid #F5A000",
            borderRadius: "0 10px 10px 0",
            color: "#526B8D",
            lineHeight: 1.7,
          }}
        >
          <strong style={{ color: "#071A3D" }}>Key relation:</strong>{" "}
          T² ∝ a³
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';

export default function EscapeSpeedVisualizer() {
  const [v0, setV0] = useState(8); // launch speed in km/s
  const [isLaunching, setIsLaunching] = useState(false);
  const [posY, setPosY] = useState(180);
  const [statusText, setStatusText] = useState("Ready to launch");

  const ve = 11.2; // km/s

  const handleLaunch = () => {
    setIsLaunching(true);
    setPosY(180);

    if (v0 < ve) {
      setStatusText(`Launching at ${v0} km/s (v₀ < vₑ). Object will fall back!`);
    } else {
      setStatusText(`Launching at ${v0} km/s (v₀ ≥ vₑ). Object ESCAPES Earth's gravity! 🚀`);
    }
  };

  useEffect(() => {
    if (!isLaunching) return;

    let frameId;
    let currentY = 180;
    let velocity = v0;

    const animate = () => {
      if (v0 < ve) {
        // Projectile goes up, slows down, falls back
        currentY -= velocity * 0.8;
        velocity -= 0.25;

        setPosY(currentY);

        if (currentY >= 180 && velocity < 0) {
          setPosY(180);
          setIsLaunching(false);
          setStatusText(`Fell back to Earth. (Peak height reached)`);
          return;
        }
      } else {
        // Projectile escapes canvas
        currentY -= velocity * 0.6;
        setPosY(currentY);

        if (currentY <= -30) {
          setIsLaunching(false);
          setStatusText(`Successfully escaped into interstellar space! ✨`);
          return;
        }
      }

      frameId = requestAnimationFrame(animate);
    };

    frameId = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(frameId);
  }, [isLaunching, v0]);

  return (
    <div style={{ background: '#FFFFFF', border: '1px solid #E7ECF3', borderRadius: '18px', padding: '24px', margin: '20px 0' }}>
      <h4 style={{ fontSize: '18px', fontWeight: '700', color: '#071A3D', marginBottom: '16px' }}>
        🚀 Escape Speed (vₑ) Launch Simulation
      </h4>

      <div style={{ background: '#071A3D', borderRadius: '14px', padding: '20px', display: 'flex', flexDirection: 'column', alignItems: 'center', position: 'relative', overflow: 'hidden' }}>
        <svg width="100%" height="240" viewBox="0 0 500 240" style={{ maxWidth: '500px' }}>
          {/* Earth Horizon Arc */}
          <path d="M 50 250 A 200 200 0 0 1 450 250 Z" fill="#2563EB" stroke="#1D4ED8" strokeWidth="2" />
          <text x="250" y="220" textAnchor="middle" fill="#FFFFFF" fontSize="13" fontWeight="700">Earth Surface</text>

          {/* Projectile Rocket/Object */}
          <circle cx="250" cy={posY} r="8" fill="#F5A000" stroke="#FFFFFF" strokeWidth="2" />

          {/* Trajectory line if launched */}
          {isLaunching && (
            <line x1="250" y1="190" x2="250" y2={posY} stroke="#F5A000" strokeWidth="2" strokeDasharray="3 3" />
          )}

          {/* Status Label Overlay */}
          <rect x="20" y="20" width="460" height="36" rx="8" fill="rgba(255, 255, 255, 0.12)" />
          <text x="250" y="43" textAnchor="middle" fill="#FFFFFF" fontSize="13" fontWeight="600">
            {statusText}
          </text>
        </svg>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', width: '100%', marginTop: '12px' }}>
          <div style={{ background: 'rgba(255, 255, 255, 0.08)', borderRadius: '10px', padding: '12px', textAlign: 'center', color: '#FFFFFF' }}>
            <div style={{ fontSize: '12px', opacity: 0.8 }}>Earth Escape Velocity:</div>
            <div style={{ fontSize: '18px', fontWeight: '800', color: '#F5A000' }}>vₑ = √(2gR) = 11.2 km/s</div>
          </div>
          <div style={{ background: 'rgba(255, 255, 255, 0.08)', borderRadius: '10px', padding: '12px', textAlign: 'center', color: '#FFFFFF' }}>
            <div style={{ fontSize: '12px', opacity: 0.8 }}>Selected Launch Velocity:</div>
            <div style={{ fontSize: '18px', fontWeight: '800', color: v0 >= ve ? '#16A34A' : '#DC2626' }}>
              v₀ = {v0} km/s ({v0 >= ve ? 'Escapes!' : 'Falls Back'})
            </div>
          </div>
        </div>
      </div>

      <div style={{ marginTop: '20px', display: 'flex', gap: '16px', alignItems: 'center', flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: '200px' }}>
          <label style={{ fontSize: '13px', fontWeight: '700', color: '#071A3D', display: 'block', marginBottom: '6px' }}>
            Launch Velocity (v₀): {v0} km/s
          </label>
          <input type="range" min="1" max="15" step="0.5" value={v0} onChange={e => setV0(parseFloat(e.target.value))} disabled={isLaunching} style={{ width: '100%', cursor: 'pointer' }} />
        </div>

        <button className="btn btn-orange" onClick={handleLaunch} disabled={isLaunching} style={{ height: '44px' }}>
          {isLaunching ? 'Launching...' : '🚀 Launch Rocket'}
        </button>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';

export default function EarthSatelliteVisualizer() {
  const [hKm, setHKm] = useState(1000); // height in km
  const canvasRef = useRef(null);

  const RE = 6400; // km
  const rTotal = RE + hKm;

  // Orbital speed vo = sqrt(GM / r) -> scaled for earth surface vo ~ 7.9 km/s
  const vo = 7.92 * Math.sqrt(RE / rTotal);

  // Time period T = 2pi * sqrt(r^3 / GM) in minutes -> surface T ~ 84 min
  const T = 84.4 * Math.pow(rTotal / RE, 1.5);
  const T_hours = (T / 60).toFixed(2);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let frameId;
    let angle = 0;

    const width = canvas.width;
    const height = canvas.height;
    const cx = width / 2;
    const cy = height / 2;

    const earthRadiusPx = 50;
    const orbitRadiusPx = earthRadiusPx + (hKm / 6400) * 45;

    const animate = () => {
      ctx.clearRect(0, 0, width, height);

      // Earth
      ctx.beginPath();
      ctx.arc(cx, cy, earthRadiusPx, 0, 2 * Math.PI);
      ctx.fillStyle = '#2563EB';
      ctx.fill();
      ctx.strokeStyle = '#1D4ED8';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.fillStyle = '#FFFFFF';
      ctx.font = 'bold 12px Inter';
      ctx.textAlign = 'center';
      ctx.fillText('Earth', cx, cy + 4);

      // Orbit Path
      ctx.beginPath();
      ctx.arc(cx, cy, orbitRadiusPx, 0, 2 * Math.PI);
      ctx.strokeStyle = '#F5A000';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([4, 4]);
      ctx.stroke();
      ctx.setLineDash([]);

      // Satellite Position
      const sx = cx + orbitRadiusPx * Math.cos(angle);
      const sy = cy + orbitRadiusPx * Math.sin(angle);

      // Draw Satellite
      ctx.beginPath();
      ctx.arc(sx, sy, 7, 0, 2 * Math.PI);
      ctx.fillStyle = '#F5A000';
      ctx.fill();
      ctx.strokeStyle = '#FFFFFF';
      ctx.lineWidth = 2;
      ctx.stroke();

      // Satellite solar panels
      ctx.fillRect(sx - 12, sy - 2, 6, 4);
      ctx.fillRect(sx + 6, sy - 2, 6, 4);

      // Speed inversely proportional to orbit radius
      const angularSpeed = 0.05 * Math.pow(RE / rTotal, 1.5);
      angle += angularSpeed;

      frameId = requestAnimationFrame(animate);
    };

    animate();
    return () => cancelAnimationFrame(frameId);
  }, [hKm]);

  return (
    <div style={{ background: '#FFFFFF', border: '1px solid #E7ECF3', borderRadius: '18px', padding: '24px', margin: '20px 0' }}>
      <h4 style={{ fontSize: '18px', fontWeight: '700', color: '#071A3D', marginBottom: '16px' }}>
        🛰️ Earth Satellite Orbital Motion Simulator
      </h4>

      <div style={{ background: '#F7F9FC', borderRadius: '14px', padding: '20px', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
        <canvas ref={canvasRef} width={500} height={240} style={{ maxWidth: '500px', width: '100%', height: 'auto' }} />

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '12px', width: '100%', marginTop: '12px' }}>
          <div style={{ background: '#EFF6FF', border: '1px solid #2563EB', borderRadius: '12px', padding: '12px', textAlign: 'center' }}>
            <span style={{ fontSize: '12px', color: '#526B8D' }}>Orbital Speed (vₒ):</span>
            <div style={{ fontSize: '20px', fontWeight: '800', color: '#071A3D' }}>{vo.toFixed(2)} km/s</div>
            <span style={{ fontSize: '11px', color: '#2563EB' }}>vₒ = √(GM / r)</span>
          </div>

          <div style={{ background: '#FFF9EE', border: '1px solid #F5A000', borderRadius: '12px', padding: '12px', textAlign: 'center' }}>
            <span style={{ fontSize: '12px', color: '#526B8D' }}>Time Period (T):</span>
            <div style={{ fontSize: '20px', fontWeight: '800', color: '#071A3D' }}>{T.toFixed(1)} mins</div>
            <span style={{ fontSize: '11px', color: '#F5A000' }}>({T_hours} hours per orbit)</span>
          </div>
        </div>
      </div>

      <div style={{ marginTop: '20px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
          <label style={{ fontSize: '14px', fontWeight: '700', color: '#071A3D' }}>
            Satellite Altitude Above Earth (h):
          </label>
          <span style={{ fontSize: '14px', fontWeight: '700', color: '#F5A000' }}>
            h = {hKm} km (r = {rTotal} km)
          </span>
        </div>
        <input type="range" min="400" max="20000" step="400" value={hKm} onChange={e => setHKm(Number(e.target.value))} style={{ width: '100%', cursor: 'pointer' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', color: '#8A9AB2', marginTop: '4px' }}>
          <span>LEO (400 km)</span>
          <span>Medium (5,000 km)</span>
          <span>High (20,000 km)</span>
        </div>
      </div>
    </div>
  );
}
